  if (str_contains($n,'doep')||str_contains($n,'drug offender')) return 'doep';
  if (str_contains($n,'life')||str_contains($n,'anti')||str_contains($n,'anti-theft')) return 'lsat';
  if (str_contains($n,'bipp')) return 'bipp';
  return 'other';
}


