<?php
/**
 * lakeview – BIPP Virtual Intake Packet
 * ------------------------------------
 * • GET  : render multi‑step form  (HTML follows this PHP section)
 * • POST : CSRF check → validate → INSERT into clinicnotepro_lakeview.intake_packet
 *          → e‑mail staff → confirmation screen
 *
 * Uses the **shared** /config/config.php instead of hard‑coded creds.
 */

declare(strict_types=1);
ob_start();
session_start();

/* ------------------------------------------------------------------ */
/* 0.  CONFIG + DB CONNECTION                                          */
/* ------------------------------------------------------------------ */
const ADMIN_ALERT_EMAIL = 'admin@notesao.com';

require_once dirname(__DIR__) . '/config/config.php';   // provides $link + $default_program_id
/** @var mysqli $link */
$db = $link;
$db->set_charset('utf8mb4');

/* Program list for selector and validation */
$programs = [];
$tbl = null;
foreach (['program','programs'] as $t) {
    $res = $db->query("SHOW TABLES LIKE '$t'");
    if ($res && $res->num_rows) { $tbl = $t; break; }
}
if ($tbl) {
    $cols = [];
    if ($res = $db->query("SHOW COLUMNS FROM `$tbl`")) {
        while ($r = $res->fetch_assoc()) { $cols[$r['Field']] = true; }
    }
    $idCol = isset($cols['id']) ? 'id' : (isset($cols['program_id']) ? 'program_id' : null);
    $labelCol = null;
    foreach (['name','program_name','title','label','program'] as $c) {
        if (isset($cols[$c])) { $labelCol = $c; break; }
    }
    if ($idCol && $labelCol) {
        $sql = "SELECT `$idCol` AS id, `$labelCol` AS label
                FROM `$tbl`
                WHERE `$labelCol` IS NOT NULL AND `$labelCol` <> ''
                ORDER BY `$labelCol`";
        if ($res = $db->query($sql)) {
            while ($r = $res->fetch_assoc()) {
                $programs[(int)$r['id']] = $r['label'];
            }
        }
    }
}




/* ------------------------------------------------------------------ */
/* 1.  HELPERS                                                         */
/* ------------------------------------------------------------------ */
function csrf_token(): string
{
    return $_SESSION['csrf'] ??= bin2hex(random_bytes(32));
}
function csrf_check(): void
{
    if (!isset($_POST['csrf_token']) || !hash_equals($_SESSION['csrf'], $_POST['csrf_token'])) {
        http_response_code(403); exit('Invalid CSRF token');
