  function validateStep(fs){
    let ok = true;
    let firstBad = null;

    // collect required and visible fields
    const required = Array.from(fs.querySelectorAll('[required]')).filter(isVisible);

    // group radios by name
    const radiosByName = {};
    required.forEach(el => {
      if (el.type === 'radio' && el.name) {
        (radiosByName[el.name] ||= []).push(el);
      }
    });

    // validate radios as groups
    Object.keys(radiosByName).forEach(name => {
      const group = radiosByName[name];
      const anyChecked = group.some(r => r.checked);
      if (!anyChecked) {
        ok = false;
        if (!firstBad) firstBad = group[0];
        group.forEach(r => r.classList.add('invalid-field'));
      } else {
        group.forEach(r => r.classList.remove('invalid-field'));
      }
    });

    // validate non-radio requireds
    required.forEach(el => {
      if (el.type === 'radio') return; // handled above
      let valid = true;
      if (el.type === 'checkbox') {
        valid = el.checked;
      } else if (el.tagName === 'SELECT' || el.tagName === 'TEXTAREA' || el.tagName === 'INPUT') {
        valid = (el.value ?? '').trim() !== '';
      }
      if (!valid) {
        ok = false;
        if (!firstBad) firstBad = el;
        el.classList.add('invalid-field');
      } else {
        el.classList.remove('invalid-field');
      }
    });


    // BIPP 9A "Other" reason requires explanation if selected
    if (ok && fs.querySelector('#other_reason_text_container')) {
      const otherChecked = !!fs.querySelector('#other_reason:checked');
      const input = fs.querySelector('#other_reason_text');
      if (otherChecked && input && input.value.trim() === ''){
        ok = false; firstBad = input; input.classList.add('invalid-field');
      }
    }

    if (!ok){
      if (alertBox){
        alertBox.textContent = 'Please complete the required fields on this page.';
        alertBox.style.display = 'block';
      }
      firstBad?.scrollIntoView({behavior:'smooth', block:'center'});
    } else {
      if (alertBox) alertBox.style.display = 'none';
    }
    return ok;
  }

